    /**
     * Parse the raw table into JSON trees.
     *
     * @return key to parsed JSON (fresh map per call)
     */
    public static Map<String, JsonElement> load() {
        Map<String, JsonElement> out = new LinkedHashMap<String, JsonElement>();
        for (Map.Entry<String, String> e : RAW.entrySet()) {
            out.put(e.getKey(), new JsonParser().parse(e.getValue()));
        }
        return out;
    }

    /**
     * @return all keys of this table
     */
    public static java.util.Set<String> keys() {
        return RAW.keySet();
    }

